cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,v in enumerate(row) if v}
placements=[]
for r in range(4):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: placements.append(('sq',sq))
  for miss in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   shape={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
   if shape<=cells: placements.append(('L'+str(miss),shape))
sol=[]
def search(left, chosen):
 if not left:
  sol.append(chosen); return
 x=min(left)
 for typ,p in placements:
  if x in p and p<=left: search(left-p,chosen+[(typ,p)])
search(cells,[])
len(cells),len(sol), [[(x,sorted(p)) for x,p in s] for s in sol[:5]]
